function telegramSupportPlan(update, settings) {
  const message = update?.message;
  const chatId = message?.chat?.id;
  const userId = message?.from?.id;
  const messageId = message?.message_id;
  if (
    !Number.isSafeInteger(chatId) ||
    !Number.isSafeInteger(userId) ||
    userId <= 0 ||
    !Number.isSafeInteger(messageId) ||
    messageId <= 0 ||
    message.sender_chat ||
    message.from?.is_bot !== false ||
    typeof message.text !== "string" ||
    !message.text.trim()
  )
    return null;
  const privateChat = message.chat.type === "private" && chatId === userId;
  const groupChat = ["group", "supergroup"].includes(message.chat.type) && chatId < 0;
  if (!privateChat && !groupChat) return null;
  const threadId = message.is_topic_message === true ? message.message_thread_id : null;
  if (
    message.is_topic_message === true &&
    (!groupChat || !Number.isSafeInteger(threadId) || threadId <= 0)
  )
    return null;
  const email = settings.requesters?.[chatId + ":" + userId];
  if (typeof email !== "string" || !/^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,63}$/i.test(email))
    return null;
  if (
    !/^[1-9][0-9]{0,19}$/.test(settings.boardId) ||
    !/^[a-zA-Z0-9_]+$/.test(settings.refundGroup) ||
    !/^[a-zA-Z0-9_]+$/.test(settings.complaintGroup) ||
    settings.refundGroup === settings.complaintGroup ||
    !/^[1-9][0-9]{0,15}$/.test(settings.botId)
  )
    throw Error("Set the Telegram bot user ID and monday board and two distinct group IDs");
  const text = message.text;
  if (text.length > 8192) throw Error("Unexpected Telegram text length");
  const refund = text.includes("refund");
  const type = refund ? "refund" : "complaint";
  const subject = Array.from(text.replace(/\s+/g, " ").trim()).slice(0, 255).join("");
  const description =
    "<p>" +
    text
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replace(/\r\n?|\n/g, "<br>") +
    "</p>";
  const reply = refund
    ? "Hi, thanks for sending this. We will review your request for refund as soon as possible 💶 💵 💷"
    : "Hi, thanks for sending this. We will review your complaint as soon as possible 📬 ☀️ ✅";
  return {
    key: "telegram:" + settings.botId + ":" + chatId + ":" + messageId,
    chatId: String(chatId),
    messageId,
    botId: String(settings.botId),
    threadId,
    type,
    subject,
    boardId: String(settings.boardId),
    groupId: refund ? settings.refundGroup : settings.complaintGroup,
    reply,
    ticket: { email, subject, description, tags: [type], status: 3, priority: 1, source: 2 },
  };
}

export default async ({ event, config }, context) => {
  const plan = telegramSupportPlan(event, config);
  if (!plan || (await context.state.get(plan.key))) return { ready: false, plan: {}, ticket: {} };
  if (!/^https:\/\/[^\s?#]+\/[^\s?#]+$/.test(config.callbackUrl))
    throw Error("Set the exact HTTPS Telegram callback shown in the trigger");
  const bot = await context.actions.call("telegram.get_webhook_info", {});
  if (bot.url !== config.callbackUrl)
    throw Error("The connected Telegram bot has a different webhook");
  if (!(await context.state.insert(plan.key, { phase: "freshdesk_pending" })))
    return { ready: false, plan: {}, ticket: {} };
  return { ready: true, plan, ticket: plan.ticket };
};

