function confirmFreshdeskSupportTicket(plan, body) {
  if (
    !Number.isSafeInteger(body?.id) ||
    body.id <= 0 ||
    body.subject !== plan.ticket.subject ||
    (typeof body.email === "string" && body.email.toLowerCase() !== plan.ticket.email.toLowerCase())
  ) {
    throw Error("Check Freshdesk before repeating ticket creation");
  }
  return { id: body.id, subject: body.subject };
}

function confirmTelegramSupportReply(plan, result) {
  const messageId = result?.messageId ?? result?.message_id;
  const threadId = result?.messageThreadId ?? result?.message_thread_id;
  if (
    !Number.isSafeInteger(messageId) ||
    messageId <= 0 ||
    String(result.chat?.id) !== plan.chatId ||
    String(result.from?.id) !== plan.botId ||
    result.text !== plan.reply ||
    (plan.threadId !== null && threadId !== undefined && threadId !== plan.threadId)
  ) {
    throw Error("Check the original Telegram conversation before resending");
  }
  return messageId;
}

function mondaySupportItem(plan, ticket) {
  return {
    board_id: plan.boardId,
    group_id: plan.groupId,
    item_name: plan.type === "refund" ? ticket.subject : plan.subject,
  };
}

function confirmMondaySupportItem(expected, item) {
  if (
    !/^[1-9][0-9]{0,19}$/.test(String(item?.id)) ||
    String(item.board?.id) !== expected.board_id ||
    item.group?.id !== expected.group_id ||
    item.name !== expected.item_name
  ) {
    throw Error("Check the configured monday group before creating another item");
  }
  return String(item.id);
}

export default async ({ plan, body, statusCode, bodyEncoding }, context) => {
  const state = {
    type: plan.type,
    chatId: plan.chatId,
    messageId: plan.messageId,
    ticketId: null,
    telegramReplyId: null,
    mondayItemId: null,
  };
  let phase = "freshdesk";
  try {
    if (statusCode !== 201 || bodyEncoding != null)
      throw Error("Missing Freshdesk creation receipt");
    const ticket = confirmFreshdeskSupportTicket(plan, body);
    state.ticketId = ticket.id;
    phase = "telegram";
    await context.state.set(plan.key, { phase, ticketId: ticket.id });
    const reply = await context.actions.call("telegram.send_message", {
      chatId: plan.chatId,
      text: plan.reply,
      replyToMessageId: plan.messageId,
      ...(plan.threadId === null ? {} : { messageThreadId: plan.threadId }),
    });
    state.telegramReplyId = confirmTelegramSupportReply(plan, reply);
    phase = "monday";
    await context.state.set(plan.key, {
      phase,
      ticketId: ticket.id,
      telegramReplyId: state.telegramReplyId,
    });
    const request = mondaySupportItem(plan, ticket);
    const response = await context.actions.call("monday.create_item", request);
    state.mondayItemId = confirmMondaySupportItem(request, response.item);
  } catch {
    return { result: { ...state, status: phase + "_unconfirmed" } };
  }
  await context.state.set(plan.key, {
    phase: "done",
    ticketId: state.ticketId,
    mondayItemId: state.mondayItemId,
  });
  return { result: { ...state, status: "confirmed" } };
};
